def page(g):
    depth = 1
    vids = pick(*g["videos"])
    faq_html = "".join(f"<details><summary>{q}</summary><p>{a}</p></details>" for q, a in g["faq"])
    others = "".join(f'<a href="{x["slug"]}.html">{re.sub("<[^>]+>","",x["h1"])}</a>' for x in GUIDES if x["slug"] != g["slug"])
    src = f'<p class="source">{g["source"]}</p>' if g["source"] else ""
    body = f"""
<section class="hero"><div class="wrap">
  <p class="crumbs"><a href="../index.html">Home</a> &rsaquo; <a href="index.html">Guides</a></p>
  <span class="eyebrow">Guide &middot; Updated October 2026</span>
  <h1>{g['h1']}</h1>
</div></section>
<section class="band"><div class="wrap prose">
{g['body']}
{src}
</div></section>
<section class="band sand"><div class="wrap">
  <span class="eyebrow">Watch</span>
  <h2>{g.get('watch_h', 'Indians who <em>did it first.</em>')}</h2>
  <div style="margin-top:36px">{yt_grid(vids, 'c3' if len(vids) > 2 else 'c2')}</div>
</div></section>
<section class="band"><div class="wrap">
  <span class="eyebrow">Quick answers</span>
  <div style="margin-top:20px; max-width:880px">{faq_html}</div>
  <h3 style="margin-top:44px">More guides</h3>
  <div class="chips" style="margin-top:16px">{others}</div>
</div></section>
""" + cta_banner("Want it planned for you?", "Send dates, group size and budget. We reply the same day with a plan and real prices.", "Hi, I read your guide: " + re.sub("<[^>]+>","",g["h1"]))
    schema = crumb_schema([("Guides", "guides/index.html"), (re.sub("<[^>]+>","",g["h1"]), f"guides/{g['slug']}.html")]) + "\n" + faq_schema([(q, re.sub("&#8377;","Rs ",a)) for q, a in g["faq"]]) + "\n" + video_schema(vids)
    schema += f'\n<script type="application/ld+json">{{"@context":"https://schema.org","@type":"Article","headline":{json_str(re.sub("<[^>]+>","",g["h1"]))},"dateModified":"2026-10-15","author":{{"@type":"Organization","name":"Sri Lanka for Indians"}},"publisher":{{"@type":"Organization","name":"Sri Lanka for Indians"}},"image":"https://i.ytimg.com/vi/{vids[0]["id"]}/hqdefault.jpg"}}</script>'
    return head(g["title"], g["desc"], f"guides/{g['slug']}.html", depth, schema, og_image=f"https://i.ytimg.com/vi/{vids[0]['id']}/hqdefault.jpg") + header(depth) + body + footer(depth)

def hub():
    depth = 1
    cards = "".join(f'<a class="card link-card" href="{g["slug"]}.html"><span class="tag">Guide</span><h3>{g["h1"]}</h3><p>{g["card"]}</p><span class="go">Read &rarr;</span></a>' for g in GUIDES)
    body = f"""
<section class="hero"><div class="wrap">
  <p class="crumbs"><a href="../index.html">Home</a> &rsaquo; Guides</p>
  <span class="eyebrow">Guides</span>
  <h1>Straight answers to <em>what Indians search for.</em></h1>
  <p class="lead">Visas, costs, routes, rupee trade and the comparisons CFOs ask about. Updated October 2026.</p>
</div></section>
<section class="band"><div class="wrap"><div class="grid c3">{cards}</div></div></section>
""" + cta_banner("Question not answered here?", "Ask us on WhatsApp. A real person replies.", "Hi, I have a question about Sri Lanka: ")
    return head("Sri Lanka Guides for Indians | Sri Lanka for Indians",
                "Practical Sri Lanka guides for Indians: free ETA visa, trading in rupees, trip cost, honeymoon, Ramayana trail, ferry from Nagapattinam, UPI and SIM, best time to visit and Port City vs GIFT City vs Dubai.",
                "guides/index.html", depth, crumb_schema([("Guides","guides/index.html")])) + header(depth) + body + footer(depth)

def build(write):
    write("guides/index.html", hub())
    for g in GUIDES:
        write(f"guides/{g['slug']}.html", page(g))
